import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from 'firebase/auth';
import type { Auth, User } from 'firebase/auth';
import { ensureWordPressUser, AuthApiError } from './authApi';
import type { WordPressSignupPayload } from './authApi';
import { validateDisplayName } from '../utils/signupValidation';
import { validateEmail } from '../utils/emailValidation';

export interface EmailSignupInput {
  email: string;
  password: string;
  displayName: string;
  firstName?: string;
  recaptchaToken: string;
  source: WordPressSignupPayload['source'];
  optIn: boolean;
}

// Provider operations are injectable so failure/retry boundaries can be tested
// without creating real accounts or bypassing production CAPTCHA enforcement.
export interface EmailSignupDependencies {
  create: (auth: Auth, email: string, password: string) => Promise<{ user: User }>;
  signIn: (auth: Auth, email: string, password: string) => Promise<{ user: User }>;
  complete: typeof ensureWordPressUser;
}
const providers: EmailSignupDependencies = {
  create: createUserWithEmailAndPassword,
  signIn: signInWithEmailAndPassword,
  complete: ensureWordPressUser,
};
const pending = new WeakSet<Auth>();

export async function completeEmailSignup(
  auth: Auth,
  input: EmailSignupInput,
  dependencies: EmailSignupDependencies = providers,
): Promise<{ user: User; wpUserId: number; created: boolean }> {
  const email = input.email.trim();
  const displayName = input.displayName.trim();
  const nameCheck = validateDisplayName(displayName);
  const emailCheck = validateEmail(email);
  if (!nameCheck.isValid) {
    throw new AuthApiError(nameCheck.error || 'Please enter a valid name.', 'invalid_name', 400);
  }
  if (input.firstName !== undefined && !validateDisplayName(input.firstName).isValid) {
    throw new AuthApiError('Please enter a valid name.', 'invalid_name', 400);
  }
  if (!emailCheck.isValid) {
    throw new AuthApiError(
      emailCheck.error || 'Please enter a valid email address.',
      'invalid_email',
      400,
    );
  }
  if (!input.recaptchaToken || input.recaptchaToken === '[empty]') {
    throw new AuthApiError('Please complete the CAPTCHA.', 'captcha_failed', 400);
  }
  if (pending.has(auth)) {
    throw new AuthApiError('Signup is already in progress.', 'signup_pending', 409);
  }
  pending.add(auth);
  try {
    let user: User;
    let created = true;
    try {
      ({ user } = await dependencies.create(auth, email, input.password));
    } catch (error) {
      if ((error as { code?: string })?.code !== 'auth/email-already-in-use') {
        throw error;
      }
      // Prove ownership with the entered password, including after a page reload.
      // Never adopt an arbitrary current session or look up users by email alone.
      ({ user } = await dependencies.signIn(auth, email, input.password));
      created = false;
    }
    if (auth.currentUser?.uid !== user.uid) {
      throw new AuthApiError('Your session changed. Please sign in again.', 'session_changed', 401);
    }
    const wpUserId = await dependencies.complete(user, {
      source: input.source,
      displayName,
      recaptchaToken: input.recaptchaToken,
      optIn: input.optIn,
      ...(input.firstName !== undefined ? { firstName: input.firstName.trim() } : {}),
    });
    if (auth.currentUser?.uid !== user.uid) {
      throw new AuthApiError('Your session changed. Please sign in again.', 'session_changed', 401);
    }
    return { user, wpUserId, created };
  } finally {
    pending.delete(auth);
  }
}
