import { hebrewUnavailableMessage } from '../i18n/catalogs';
import { devWarn } from '../utils/developmentDiagnostics';
import { CanonicalPassage, VerseReference } from '../utils/verseMappings';
import {
  resolveStudyResources,
  resourceReferenceKey,
} from '../utils/verseMappings/resourceMappings';
/**
 * Strong's Concordance Service
 * Fetches Strong's definitions from static CDN files
 *
 * Data source: bible-strongs/ (served via jsdelivr CDN)
 * License: Public domain (Strong's Concordance, published 1890)
 */

const STRONGS_CDN_BASE = 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-strongs@main';

interface ResourceRequest {
  signal?: AbortSignal;
  required?: boolean;
}
export class HebrewResourceError extends Error {
  constructor(public readonly kind: 'unavailable' | 'request-failed') {
    super(
      kind === 'unavailable'
        ? 'Hebrew content is unavailable for this passage.'
        : 'Hebrew content could not be loaded.',
    );
    this.name = 'HebrewResourceError';
  }
}

async function resourceJson(url: string, signal?: AbortSignal): Promise<unknown> {
  if (signal?.aborted) {
    throw new DOMException('Cancelled', 'AbortError');
  }
  const controller = new AbortController();
  const abort = () => controller.abort();
  signal?.addEventListener('abort', abort, { once: true });
  const timeout = setTimeout(abort, 8000);
  try {
    const response = await fetch(url, { signal: controller.signal });
    if (!response.ok) {
      throw new HebrewResourceError('request-failed');
    }
    const value: unknown = await response.json();
    if (signal?.aborted) {
      throw new DOMException('Cancelled', 'AbortError');
    }
    return value;
  } finally {
    clearTimeout(timeout);
    signal?.removeEventListener('abort', abort);
  }
}

export interface StrongsEntry {
  number: string;
  language: 'hebrew' | 'greek';
  transliteration?: string;
  pronunciation?: string;
  definition: string;
  kjvTranslation?: string;
  hebrew?: string; // Hebrew text (lemma) for Hebrew entries
  greek?: string; // Greek text (lemma) for Greek entries
  verses?: string[]; // Array of verse references in format "book chapter:verse:position"
  translations?: Record<string, string>; // All language translations: { 'zh': '...', 'de': '...', 'es': '...', etc. }
}

/**
 * Determine if a Strong's number is Hebrew or Greek
 */
function getStrongsLanguage(strongsNumber: string): 'hebrew' | 'greek' {
  return strongsNumber.startsWith('H') ? 'hebrew' : 'greek';
}

/**
 * Fetch Strong's entry - tries local (public/bible-strongs) first, then CDN
 */
export const fetchStrongsEntry = async (
  strongsNumber: string,
  options: ResourceRequest = {},
): Promise<StrongsEntry | null> => {
  if (!strongsNumber) {
    return null;
  }

  // Normalize Strong's number (ensure proper format: H0001, G0001, etc.)
  const normalized = strongsNumber.toUpperCase().trim();
  const language = getStrongsLanguage(normalized);
  const langPath = language === 'hebrew' ? 'hebrew' : 'greek';

  const urls = [
    `/bible-strongs/${langPath}/entries/${normalized}.json`,
    `${STRONGS_CDN_BASE}/${langPath}/entries/${normalized}.json`,
  ];

  for (const url of urls) {
    try {
      const data = (await resourceJson(url, options.signal)) as Partial<StrongsEntry> | null;
      if (
        data &&
        data.number === normalized &&
        data.language === language &&
        typeof data.definition === 'string'
      ) {
        return data as StrongsEntry;
      }
    } catch (error) {
      if (options.signal?.aborted) {
        throw error;
      }
      // Try next URL
      continue;
    }
  }

  if (options.required) {
    throw new HebrewResourceError('request-failed');
  }
  devWarn("Strong's not found from local or CDN");
  return null;
};

/**
 * Get Strong's definition in the user's language
 * Supports all DeepL languages
 */
export const getStrongsDefinition = (entry: StrongsEntry | null, userLanguage = 'en'): string => {
  if (!entry) {
    return '';
  }

  // Map common language codes
  const langMap: Record<string, string> = {
    en: 'en',
    zh: 'zh',
    'zh-hans': 'zh',
    'zh-hant': 'zh',
    cuv: 'zh',
    de: 'de',
    lut: 'de',
    es: 'es',
    fr: 'fr',
    it: 'it',
    pt: 'pt',
    ru: 'ru',
    ja: 'ja',
    ko: 'ko',
    ar: 'ar',
    hi: 'hi',
    // Add more mappings as needed
  };

  const normalizedLang = langMap[userLanguage.toLowerCase()] || userLanguage.toLowerCase();

  if (normalizedLang !== 'en') {
    return entry.translations?.[normalizedLang]?.trim() || hebrewUnavailableMessage(normalizedLang);
  }

  // Default to English definition
  return entry.definition || entry.kjvTranslation || '';
};

/**
 * Fetch multiple Strong's entries
 */
export const fetchStrongsEntries = async (
  strongsNumbers: string[],
  options: ResourceRequest = {},
): Promise<Map<string, StrongsEntry>> => {
  const entries = new Map<string, StrongsEntry>();

  // Fetch all entries in parallel
  const promises = [...new Set(strongsNumbers)].map(async (number) => {
    const entry = await fetchStrongsEntry(number, options);
    if (entry) {
      entries.set(number, entry);
    }
  });

  await Promise.all(promises);
  return entries;
};

/**
 * Get Strong's definition for a word (with caching)
 * Supports all DeepL languages
 */
const strongsCache = new Map<string, StrongsEntry | null>();

export const getStrongsDefinitionForWord = async (
  strongsNumber: string,
  userLanguage = 'en',
): Promise<string> => {
  if (!strongsNumber) {
    return '';
  }

  // Check cache first
  let entry = strongsCache.get(strongsNumber);

  if (!entry && entry !== null) {
    // Not in cache, fetch it
    entry = await fetchStrongsEntry(strongsNumber);
    strongsCache.set(strongsNumber, entry);
  }

  return getStrongsDefinition(entry, userLanguage);
};

/**
 * Parse verse reference with position: "genesis 1:1:2" -> { book: "genesis", chapter: 1, verse: 1, position: 2 }
 */
export interface ParsedVerseRef {
  book: string;
  chapter: number;
  verse: number;
  position?: number;
}

export const parseVerseRef = (verseRef: string): ParsedVerseRef | null => {
  const parts = verseRef.split(' ');
  if (parts.length < 2) {
    return null;
  }

  const book = parts.slice(0, -1).join(' ');
  const lastPart = parts[parts.length - 1];

  // Check if it has position: "1:1:2" format
  const positionMatch = lastPart.match(/^(\d+):(\d+):(\d+)$/);
  if (positionMatch) {
    return {
      book,
      chapter: parseInt(positionMatch[1]),
      verse: parseInt(positionMatch[2]),
      position: parseInt(positionMatch[3]),
    };
  }

  // Regular format: "1:1"
  const regularMatch = lastPart.match(/^(\d+):(\d+)$/);
  if (regularMatch) {
    return {
      book,
      chapter: parseInt(regularMatch[1]),
      verse: parseInt(regularMatch[2]),
    };
  }

  return null;
};

/**
 * Word information for displaying Hebrew text in a verse
 */
export interface VerseWord {
  strongsNumber: string;
  hebrew: string;
  position: number;
  entry: StrongsEntry;
  resource?: VerseReference;
}

/**
 * Verse index cache (loaded on-demand)
 */
let verseIndexCache: Record<string, string[]> | null = null;

/**
 * Load verse index from CDN
 */
const loadVerseIndex = async (signal?: AbortSignal): Promise<Record<string, string[]>> => {
  if (verseIndexCache) {
    return verseIndexCache;
  }

  // The bundled resource is the same inventory used to validate the adapter.
  const urls = ['/bible-strongs/verse-index.json', `${STRONGS_CDN_BASE}/verse-index.json`];

  for (const url of urls) {
    try {
      const index = await resourceJson(url, signal);
      if (
        index &&
        typeof index === 'object' &&
        !Array.isArray(index) &&
        Object.keys(index).length > 0 &&
        Object.entries(index).every(
          ([key, numbers]) =>
            /^\S+ \d+:\d+$/.test(key) &&
            Array.isArray(numbers) &&
            numbers.every((number: unknown) => typeof number === 'string' && /^H\d+$/.test(number)),
        )
      ) {
        verseIndexCache = Object.fromEntries(
          Object.entries(index).map(([key, numbers]) => [key.toLowerCase(), numbers]),
        );
        return verseIndexCache;
      }
    } catch (error) {
      if (signal?.aborted) {
        throw error;
      }
      // Continue to next URL
      continue;
    }
  }

  throw new HebrewResourceError('request-failed');
};

/** Raw WLC reference only. Reader callers must use fetchHebrewWordsForPassage. */
export const fetchHebrewWordsForVerse = async (
  book: string,
  chapter: number,
  verse: number,
  signal?: AbortSignal,
): Promise<VerseWord[]> => {
  const reference = { book, chapter, verse };
  const index = await loadVerseIndex(signal);
  const numbers = index[resourceReferenceKey(reference)];
  if (!numbers?.length) {
    throw new HebrewResourceError('unavailable');
  }
  const words = await getHebrewWordsForVerse(book, chapter, verse, numbers, {
    signal,
    required: true,
  });
  if (!words.length) {
    throw new HebrewResourceError('unavailable');
  }
  return words.map((word) => ({ ...word, resource: reference }));
};

/** Complete canonical span, ordered by resource and occurrence; no partial success. */
export const fetchHebrewWordsForPassage = async (
  passage: CanonicalPassage,
  signal?: AbortSignal,
): Promise<VerseWord[]> => {
  const resolution = resolveStudyResources(passage, 'hebrew-wlc');
  if (resolution.status === 'unavailable') {
    throw new HebrewResourceError('unavailable');
  }
  const groups = await Promise.all(
    resolution.references.map((ref) =>
      fetchHebrewWordsForVerse(ref.book, ref.chapter, ref.verse, signal),
    ),
  );
  if (signal?.aborted) {
    throw new DOMException('Cancelled', 'AbortError');
  }
  return groups.flat();
};

/**
 * Get Hebrew words for a verse given Strong's numbers
 * This is the recommended approach - use known Strong's numbers from verse data
 */
export const getHebrewWordsForVerse = async (
  book: string,
  chapter: number,
  verse: number,
  strongsNumbers: string[],
  options: ResourceRequest = {},
): Promise<VerseWord[]> => {
  // Normalize book name: trim and collapse multiple spaces, then lowercase
  const normalizedBook = (book || '').toLowerCase().trim().replace(/\s+/g, ' ');

  const words: VerseWord[] = [];

  // Fetch all Strong's entries in parallel
  const entries = await fetchStrongsEntries(strongsNumbers, options);

  // Extract words that appear in this verse, with their positions
  // Note: entries may use camelCase (e.g., "firstSamuel") while normalizedBook is lowercase
  // We need to match case-insensitively
  const normalizedBookLower = normalizedBook.toLowerCase().replace(/\s+/g, '');
  const seen = new Set<string>();

  for (const [strongsNumber, entry] of entries.entries()) {
    if (!entry.verses || entry.verses.length === 0 || !entry.hebrew) {
      if (options.required) {
        throw new HebrewResourceError('unavailable');
      }
      continue;
    }

    for (const verseRef of entry.verses) {
      const parsed = parseVerseRef(verseRef);
      if (!parsed) {
        continue;
      }

      const entryBookNormalized = parsed.book.toLowerCase().trim().replace(/\s+/g, '');
      const matchesBook = entryBookNormalized === normalizedBookLower;
      const matchesChapter = Number(parsed.chapter) === Number(chapter);
      const matchesVerse = Number(parsed.verse) === Number(verse);
      const hasPosition = parsed.position !== undefined;

      if (
        matchesBook &&
        matchesChapter &&
        matchesVerse &&
        hasPosition &&
        parsed.position !== undefined
      ) {
        const occurrence = `${strongsNumber}:${parsed.position}`;
        if (seen.has(occurrence)) {
          continue;
        }
        seen.add(occurrence);
        words.push({
          strongsNumber,
          hebrew: entry.hebrew,
          position: parsed.position,
          entry,
        });
      }
    }
  }

  if (
    options.required &&
    [...entries.keys()].some((number) => !words.some((word) => word.strongsNumber === number))
  ) {
    throw new HebrewResourceError('unavailable');
  }
  // Sort by position to get correct word order
  words.sort((a, b) => a.position - b.position);

  return words;
};
