import { getModalSurface } from '../../utils/modalSurface';
import CloseIcon from '@mui/icons-material/Close';
import { Box, Button, IconButton, Typography } from '@mui/material';
import React, { useCallback, useEffect, useState } from 'react';
import { Link as RouterLink, useLocation } from 'react-router-dom';

import { useTranslation } from '../../hooks/useTranslation';
import { ConversionEvents } from '../../utils/analytics';

/** Routes that already include signup or must not be interrupted by the reading invitation. */
const DEFAULT_DISABLED_PATHS: readonly string[] = ['/login'];

const SCROLL_SIGNUP_DISMISSED_KEY = 'revelationaryScrollSignupDismissed';

function readScrollSignupDismissed(): boolean {
  if (typeof window === 'undefined') {
    return false;
  }
  try {
    return window.localStorage.getItem(SCROLL_SIGNUP_DISMISSED_KEY) === '1';
  } catch {
    return false;
  }
}

interface ScrollTriggeredSignupProps {
  threshold?: number;
  rootMargin?: string;
  /** When false, reading invitation is disabled to avoid flashing it before Firebase resolves auth. */
  authReady: boolean;
  loggedIn: boolean;
  /** Pathnames (e.g. `/login`) where scroll signup never runs. */
  disabledPaths?: readonly string[];
}

/**
 * After the user scrolls past a threshold while logged out, shows a compact
 * non-modal invitation to track reading. Users can dismiss it and keep reading; dismissal is remembered
 * in localStorage for future visits.
 */
const ScrollTriggeredSignup: React.FC<ScrollTriggeredSignupProps> = ({
  threshold = 0.25,
  rootMargin: _rootMargin = '0px',
  authReady,
  loggedIn,
  disabledPaths = DEFAULT_DISABLED_PATHS,
}) => {
  const { pathname } = useLocation();
  const { t } = useTranslation();
  const routeDisabled = pathname !== '/' || disabledPaths.includes(pathname);
  const [showSignup, setShowSignup] = useState(false);
  const [scrollSignupDismissed, setScrollSignupDismissed] = useState(readScrollSignupDismissed);

  const handleDismiss = useCallback(() => {
    ConversionEvents.scrollSignupDismissed();
    try {
      window.localStorage.setItem(SCROLL_SIGNUP_DISMISSED_KEY, '1');
    } catch {
      // ignore quota / private mode
    }
    setScrollSignupDismissed(true);
    setShowSignup(false);
  }, []);

  useEffect(() => {
    if (loggedIn) {
      setShowSignup(false);
    }
  }, [loggedIn]);

  useEffect(() => {
    if (routeDisabled) {
      setShowSignup(false);
    }
  }, [routeDisabled]);

  useEffect(() => {
    if (!authReady || loggedIn || routeDisabled || scrollSignupDismissed) {
      return;
    }

    const handleScroll = () => {
      const scrollPosition = window.scrollY;
      const windowHeight = window.innerHeight;
      const documentHeight = document.documentElement.scrollHeight;
      const scrollable = documentHeight - windowHeight;
      if (scrollable <= 0) {
        return;
      }
      const scrollPercentage = scrollPosition / scrollable;
      if (scrollPercentage > threshold) {
        setShowSignup(true);
      }
    };

    handleScroll();
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [authReady, loggedIn, routeDisabled, scrollSignupDismissed, threshold]);

  useEffect(() => {
    if (showSignup && authReady && !loggedIn && !routeDisabled) {
      ConversionEvents.scrollSignupShown();
    }
  }, [showSignup, authReady, loggedIn, routeDisabled]);

  const promptVisible =
    showSignup && authReady && !loggedIn && !routeDisabled && !scrollSignupDismissed;

  useEffect(() => {
    if (!promptVisible) {
      return;
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        handleDismiss();
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [promptVisible, handleDismiss]);

  if (!promptVisible) {
    return null;
  }

  return (
    <Box
      sx={{
        position: 'fixed',
        bottom: 'calc(16px + env(safe-area-inset-bottom, 0px))',
        right: 16,
        left: { xs: 16, sm: 'auto' },
        maxWidth: 420,
        zIndex: 1200,
        pointerEvents: 'none',
      }}
    >
      <Box
        component="aside"
        aria-label={String(t('signup.readingInvitation'))}
        sx={(theme) => ({
          ...getModalSurface(theme.palette.mode),
          p: 1.5,
          pr: 5.5,
          position: 'relative',
          pointerEvents: 'auto',
        })}
      >
        <Typography role="status" sx={{ fontSize: '0.875rem', lineHeight: 1.5 }}>
          {String(t('signup.readingInvitation'))}
        </Typography>
        <Button
          component={RouterLink}
          to="/login"
          variant="text"
          size="small"
          disableRipple
          sx={{
            mt: 0.5,
            p: 0,
            minHeight: 44,
            color: 'text.primary',
            textTransform: 'none',
            '&:focus-visible': { outline: '2px solid currentColor', outlineOffset: 2 },
          }}
        >
          {String(t('common.signIn'))}
        </Button>
        <IconButton
          aria-label={String(t('signup.closeSignupPromptAria'))}
          onClick={handleDismiss}
          disableRipple
          sx={{
            position: 'absolute',
            right: 2,
            top: 2,
            width: 44,
            height: 44,
            '&:focus-visible': { outline: '2px solid currentColor', outlineOffset: 2 },
          }}
        >
          <CloseIcon fontSize="small" />
        </IconButton>
      </Box>
    </Box>
  );
};

export default ScrollTriggeredSignup;
