// Mouse
export const handleMouseHover = (
  event: React.MouseEvent,
  setHover: React.Dispatch<
    React.SetStateAction<
      { text: string; book: string; chapter: number; verse: string | number } | undefined
    >
  >,
  setIsShown: React.Dispatch<React.SetStateAction<boolean>>,
  verse: { book: string; chapter: number; verse: string | number },
) => {
  setHover({ text: event.currentTarget.textContent || '', ...verse });
  setIsShown(true);
};

export const fetchCount = (book: string, translation = 'kjv'): number =>
  editionChapterCount(book || '', translation);

export const executeReaderIntent = async (
  intent: ResolvedReaderIntent,
  setData: React.Dispatch<React.SetStateAction<any[]>>,
  setVerse: React.Dispatch<React.SetStateAction<any[]>>,
  searchTerm: (term: string, language: string) => Promise<void>,
  setCount: React.Dispatch<React.SetStateAction<number | string>>,
  setPage: React.Dispatch<React.SetStateAction<number>>,
): Promise<void> => {
  if (intent.input.kind === 'text') {
    await searchTerm(`"${intent.input.text}"`, intent.edition);
    return;
  }
  if (!intent.passage) {
    throw new SearchInputError();
  }
  if (await fetchReaderPassage(intent.passage, setData, setVerse, intent.edition)) {
    setCount(fetchCount(intent.passage.book, intent.edition));
    setPage(intent.passage.chapter);
  }
};

export const handleSearch = async (
  e: React.KeyboardEvent<HTMLInputElement>,
  setData: React.Dispatch<React.SetStateAction<any[]>>,
  setVerse: React.Dispatch<React.SetStateAction<any[]>>,
  searchTerm: (term: string, language: string) => Promise<void>,
  setCount: React.Dispatch<React.SetStateAction<number | string>>,
  setPage: React.Dispatch<React.SetStateAction<number>>,
  setSearch?: React.Dispatch<React.SetStateAction<string>>,
  translation?: string,
  applyReaderIntent?: (intent: ResolvedReaderIntent) => void,
): Promise<void> => {
  if (e.key !== 'Enter' && e.keyCode !== 13) {
    return;
  }
  const term = (e.target as HTMLInputElement).value.trim();
  let stored: string | undefined;
  try {
    stored = localStorage.getItem('translation') || undefined;
  } catch {
    // Storage is optional; explicit/current intent is still usable.
  }
  const resolution = resolveReaderIntent(parseReaderInput(term), {
    edition: translation || Cookies.get('translation') || stored || 'kjv',
  });
  if (resolution.status === 'invalid') {
    throw new SearchInputError();
  }
  if (resolution.status !== 'resolved') {
    throw new ReaderIntentError(resolution);
  }
  setSearch?.(term);
  if (applyReaderIntent) {
    applyReaderIntent(resolution);
    return;
  }
  await executeReaderIntent(resolution, setData, setVerse, searchTerm, setCount, setPage);
};

/* DATA DRIVEN */

// Passage and keyword requests share one owner, so neither can overwrite a newer reader action.
const passageRequests = new WeakMap<React.Dispatch<React.SetStateAction<any[]>>, AbortController>();
export const cancelReaderRequest = (setData: React.Dispatch<React.SetStateAction<any[]>>) => {
  passageRequests.get(setData)?.abort();
  passageRequests.delete(setData);
};
export const beginReaderRequest = (setData: React.Dispatch<React.SetStateAction<any[]>>) => {
  cancelReaderRequest(setData);
  const controller = new AbortController();
  passageRequests.set(setData, controller);
  return controller;
};
export const finishReaderRequest = (
  setData: React.Dispatch<React.SetStateAction<any[]>>,
  controller: AbortController,
) => {
  if (passageRequests.get(setData) === controller) {
    passageRequests.delete(setData);
  }
};
export const fetchReaderPassage = async (
  passage: ReaderPassage,
  setData: React.Dispatch<React.SetStateAction<any[]>>,
  setVerse: React.Dispatch<React.SetStateAction<any[]>>,
  translation: string,
) => {
  const controller = beginReaderRequest(setData);
  window.dispatchEvent(new CustomEvent('bibleLoadError', { detail: '' }));
  try {
    const rows = [];
    const endChapter = passage.endChapter ?? passage.chapter;
    for (let chapter = passage.chapter; chapter <= endChapter; chapter++) {
      rows.push(...(await loadBibleChapter(translation, passage.book, chapter, controller.signal)));
    }
    const data = selectReaderPassageRows(rows, passage).map((row) => ({
      ...row,
      translation,
      text:
        translation === 'fbv'
          ? stripFbvCommentary(row.text, String(row.chapter), String(row.verse))
          : row.text,
    }));
    if (!controller.signal.aborted) {
      setData(data);
      setVerse(data);
      return true;
    }
  } catch {
    if (!controller.signal.aborted) {
      setData([]);
      setVerse([]);
      window.dispatchEvent(
        new CustomEvent('bibleLoadError', {
          detail: !editionHasBook(passage.book, translation)
            ? interfaceText('Chapter unavailable', {}, getBibleEdition(translation).locale)
            : 'Unable to load this Bible passage. Please try again.',
        }),
      );
    }
  } finally {
    finishReaderRequest(setData, controller);
  }
  return false;
};

export const fetchVerse = async (
  book: string,
  chapter: string | number,
  verse: string | number,
  setData: React.Dispatch<React.SetStateAction<any[]>>,
  setVerse: React.Dispatch<React.SetStateAction<any[]>>,
  translation = 'kjv',
) =>
  fetchReaderPassage(
    {
      book: book.trim(),
      chapter: Number(chapter),
      ...(verse !== '' && verse !== undefined ? { verse: String(verse) } : {}),
    },
    setData,
    setVerse,
    translation,
  );

