import { interfaceText } from '../../i18n/interfaceText';
import React from 'react';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import MenuList from '@mui/material/MenuList';
import ListItemText from '@mui/material/ListItemText';
import ListItemIcon from '@mui/material/ListItemIcon';
import Typography from '@mui/material/Typography';
import ContentCopy from '@mui/icons-material/ContentCopy';

import BorderColorIcon from '@mui/icons-material/BorderColor';

import { useTranslation } from '../../hooks/useTranslation';

interface MenuPanelProps {
  contextMenu: { mouseX: number; mouseY: number } | null;
  isHighlighted: boolean;
  handleHighlight: () => void;
  handleClose: () => void;
  selectedVerse: { text: string }[];
  loggedIn: boolean;
}

const MenuPanel: React.FC<MenuPanelProps> = ({
  contextMenu,
  isHighlighted,
  handleHighlight,
  handleClose,
  selectedVerse,
  loggedIn,
}) => {
  const { t } = useTranslation();

  if (!contextMenu || !selectedVerse) {
    return null;
  }

  // copy a verse
  const handleCopy = async () => {
    await navigator.clipboard.writeText(selectedVerse[0].text);
    await handleClose();
  };

  return (
    <>
      <Menu
        elevation={0}
        sx={{ backgroundColor: 'rgba(0, 0, 0, 0.005)' }}
        open={contextMenu !== null}
        onClose={handleClose}
        anchorReference="anchorPosition"
        anchorPosition={
          contextMenu !== null
            ? {
                top: contextMenu?.mouseY,
                left: contextMenu?.mouseX,
              }
            : undefined
        }
      >
        <MenuList dense sx={{ width: 320, maxWidth: '100%', backgroundColor: '#212121' }}>
          <MenuItem onClick={() => handleCopy()}>
            <ListItemIcon>
              <ContentCopy fontSize="small" />
            </ListItemIcon>
            <ListItemText>{interfaceText('Copy')}</ListItemText>
            <Typography variant="body2" color="text.secondary">
              {/* ⌘C */}
            </Typography>
          </MenuItem>
          {/* <MenuItem onClick={handleClose}>
          <ListItemIcon>
            <FavoriteIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Save</ListItemText>
          <Typography variant="body2" color="text.secondary">
            ⌘S
          </Typography>
        </MenuItem> */}
          {/* <MenuItem onClick={handleClose}>
          <ListItemIcon>
            <AddLinkIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Link</ListItemText>
          <Typography variant="body2" color="text.secondary">
            ⌘L
          </Typography>
        </MenuItem> */}
          <MenuItem disabled={!loggedIn} onClick={handleHighlight}>
            <ListItemIcon>
              <BorderColorIcon fontSize="small" />
            </ListItemIcon>
            <ListItemText>
              {isHighlighted
                ? String(t('highlight.removeHighlight'))
                : String(t('highlight.highlight'))}
            </ListItemText>
            <Typography variant="body2" color="text.secondary">
              {/* ⌘H */}
            </Typography>
          </MenuItem>
          {/* <MenuItem onClick={handleClose}>
          <ListItemIcon>
            <AttachFileIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Attach</ListItemText>
          <Typography variant="body2" color="text.secondary">
            ⌘A
          </Typography>
        </MenuItem>
        <MenuItem onClick={() => handleShare()}>
          <ListItemIcon>
            <ShareIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Share</ListItemText>
          <Typography variant="body2" color="text.secondary">
            ⌘O
          </Typography>
        </MenuItem> */}
          {/* <MenuItem disabled={!loggedIn} onClick={handleCommentOpen}>
            <ListItemIcon>
              <CommentIcon fontSize="small" />
            </ListItemIcon>
            <ListItemText>Add Comment</ListItemText>
          </MenuItem> */}
        </MenuList>
      </Menu>
    </>
  );
};

export default MenuPanel;
