import i18n from 'i18next';
import { readerCatalogs, readerLocale } from './catalogs';

const paths = new Map<string, [string, string]>();
for (const [section, entries] of Object.entries(readerCatalogs.en.additional.interface)) {
  for (const [key, value] of Object.entries(entries)) {
    paths.set(value, [section, key]);
  }
}
/** Resolve additional exported copy at render time, including errors produced by services. */
export function interfaceText(
  text: string,
  values: Record<string, string | number> = {},
  language = i18n.language || 'en',
): string {
  const locale = readerLocale(language) || 'en';
  const path = paths.get(text);
  const sections = readerCatalogs[locale].additional.interface as Record<
    string,
    Record<string, string>
  >;
  const translated = path ? sections[path[0]]?.[path[1]] || text : text;
  return translated.replace(/\{\{(\w+)\}\}/g, (token, key) =>
    values[key] === undefined ? token : String(values[key]),
  );
}
